private final CelPolicyCompiler scriptHost;

public CelPolicyEngine() {
    this(CelPolicyCompiler.getInstance(CelPolicyType.COMPONENT));
}

CelPolicyEngine(final CelPolicyCompiler scriptHost) {
    this.scriptHost = scriptHost;
