                    } catch (InvalidProtocolBufferException e) {
                        throw new IllegalStateException(e);
                    }
                })
                .list());
    }

    public static void truncateNotificationOutbox() {
        useJdbiHandle(handle -> handle.execute("TRUNCATE TABLE \"NOTIFICATION_OUTBOX\""));
    }
}

